fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // The problem guarantees arr1.len() == arr2.len() and arr2 contains no zeros.
    // We can assert the lengths match to catch any misuse in debug builds.
    assert_eq!(arr1.len(), arr2.len());

    // Perform element‐wise division and collect the quotients.
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a / b)
        .collect()
}

